<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\UserGrantedClientScopes;

class UserGrantedClientScopesCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(UserGrantedClientScopes $userGrantedClientScopes, ?int $size): UserGrantedClientScopesCursor
    {
        $next = clone $this;
        $next->sinceUid = $userGrantedClientScopes->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
